def _extracted_route_entrypoint(obs, config=None):
    step = int((obs.get("step", 0) if hasattr(obs, "get") else getattr(obs, "step", 0)) or 0)
    if step < len(_ROUTE):
        a = _ROUTE[step]
        if a is not None:
            return a
    return {"farmer": ["PASS"], "hands": [], "market": []}


agent = _extracted_route_entrypoint
